                case ServiceKind.ApiGateway: return new Shape(ApiGatewayPoints, ApiGatewayTriangles, ApiGatewayLoops, ApiGatewayBackground);
                case ServiceKind.Lambda: return new Shape(LambdaPoints, LambdaTriangles, LambdaLoops, LambdaBackground);
                case ServiceKind.DynamoDB: return new Shape(DynamoDBPoints, DynamoDBTriangles, DynamoDBLoops, DynamoDBBackground);
                case ServiceKind.S3: return new Shape(S3Points, S3Triangles, S3Loops, S3Background);
                case ServiceKind.SQS: return new Shape(SQSPoints, SQSTriangles, SQSLoops, SQSBackground);
                case ServiceKind.EventBridge: return new Shape(EventBridgePoints, EventBridgeTriangles, EventBridgeLoops, EventBridgeBackground);
                case ServiceKind.CloudWatch: return new Shape(CloudWatchPoints, CloudWatchTriangles, CloudWatchLoops, CloudWatchBackground);
                default: return null;
            }
        }
    }
}
